package com.propbuy.web;
import com.propbuy.repo.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.*; import org.springframework.util.StringUtils; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/properties") public class ImageController { final PropertyRepository props; final UserRepository users; final JdbcTemplate db; final Path uploadDir; ImageController(PropertyRepository p,UserRepository u,JdbcTemplate d,@Value("${app.upload-dir}") String dir){props=p;users=u;db=d;uploadDir=Path.of(dir).toAbsolutePath().normalize();}
 @PostMapping("/{propertyId}/images") @PreAuthorize("isAuthenticated()") Map<String,Object> upload(@PathVariable Long propertyId,@RequestParam("file") MultipartFile file,Authentication a)throws IOException{var p=props.findById(propertyId).orElseThrow();if(!p.getSeller().getEmail().equalsIgnoreCase(a.getName()))throw new org.springframework.security.access.AccessDeniedException("Not your property");if(file.isEmpty()||file.getSize()>10_000_000||file.getContentType()==null||!List.of("image/jpeg","image/png","image/webp").contains(file.getContentType()))throw new IllegalArgumentException("Only non-empty JPG, PNG, or WEBP images up to 10MB are accepted");var count=db.queryForObject("SELECT COUNT(*) FROM property_images WHERE property_id=?",Long.class,propertyId);if(count!=null&&count>=12)throw new IllegalStateException("A property can have at most 12 images.");Files.createDirectories(uploadDir);var extension=switch(file.getContentType()){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};var key=UUID.randomUUID()+extension;Files.copy(file.getInputStream(),uploadDir.resolve(key),StandardCopyOption.REPLACE_EXISTING);db.update("INSERT INTO property_images(property_id,storage_key,original_name,content_type,size_bytes) VALUES (?,?,?,?,?)",propertyId,key,StringUtils.cleanPath(Objects.requireNonNullElse(file.getOriginalFilename(),"image")),file.getContentType(),file.getSize());return Map.of("stored",true,"key",key,"url","/api/properties/"+propertyId+"/images/"+key);}
 @GetMapping("/{propertyId}/images") @PreAuthorize("isAuthenticated()") List<Map<String,Object>> images(@PathVariable Long propertyId,Authentication a){var p=props.findById(propertyId).orElseThrow();authorizeMetadata(p,a);var rows=db.queryForList("SELECT id,storage_key,original_name,content_type,size_bytes,created_at FROM property_images WHERE property_id=? ORDER BY created_at",propertyId);rows.forEach(row->row.put("url","/api/properties/"+propertyId+"/images/"+row.get("storage_key")));return rows;}
 @GetMapping("/published/{propertyId}") @PreAuthorize("permitAll()") List<Map<String,Object>> published(@PathVariable Long propertyId){var count=db.queryForObject("SELECT COUNT(*) FROM resale_listings WHERE property_id=? AND status='PUBLISHED'",Long.class,propertyId);if(count==null||count==0)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Published property not found");var rows=db.queryForList("SELECT id,storage_key,content_type FROM property_images WHERE property_id=? ORDER BY created_at",propertyId);rows.forEach(row->row.put("url","/api/properties/"+propertyId+"/images/"+row.get("storage_key")));return rows;}
 @GetMapping("/{propertyId}/images/{storageKey}") @PreAuthorize("permitAll()") ResponseEntity<Resource> content(@PathVariable Long propertyId,@PathVariable String storageKey,Authentication a)throws IOException{var p=props.findById(propertyId).orElseThrow();var row=db.queryForList("SELECT storage_key,content_type FROM property_images WHERE property_id=? AND storage_key=?",propertyId,storageKey).stream().findFirst().orElseThrow();var published=db.queryForObject("SELECT COUNT(*) FROM resale_listings WHERE property_id=? AND status='PUBLISHED'",Long.class,propertyId);if((published==null||published==0)&& (a==null||!canViewPrivate(p,a)))throw new org.springframework.security.access.AccessDeniedException("This image is private.");var safe=uploadDir.resolve(storageKey).normalize();if(!safe.startsWith(uploadDir))throw new org.springframework.security.access.AccessDeniedException("Invalid image path.");var resource=new FileSystemResource(safe);if(!resource.exists())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Image not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(String.valueOf(row.get("content_type")))).body(resource);}
 private void authorizeMetadata(com.propbuy.model.Property p,Authentication a){var published=db.queryForObject("SELECT COUNT(*) FROM resale_listings WHERE property_id=? AND status='PUBLISHED'",Long.class,p.getId());if((published==null||published==0)&&!canViewPrivate(p,a))throw new org.springframework.security.access.AccessDeniedException("These images are private.");}
 private boolean canViewPrivate(com.propbuy.model.Property p,Authentication a){if(a==null)return false;var u=users.findByEmailIgnoreCase(a.getName()).orElse(null);return u!=null&&(u.getRole()==com.propbuy.model.User.Role.ADMIN||p.getSeller().getId().equals(u.getId()));}
}
